// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 changeFee, uint16 feeRate) public {
        // keep feeRate admissible (reference reverts for feeRate > 5000)
        feeRate = uint16(bound(feeRate, 0, 5000));
        // only inputs where P and M must differ
        vm.assume(changeFee != 1);

        c.initialize(address(0), address(0), 1e18, 1e18, changeFee, feeRate, bytes32(0), false, false);

        assertTrue(c.changeFee() == changeFee, "changeFee must equal the initialized argument");
    }
}
